// @ts-check
// cadence-mod.mjs - the Cadence module: the in-process half of the plugin, for
// hosts that load mods. hooks/hooks.json names it under `modules`, beside the
// command hooks. A host without mods ignores that key and keeps the hooks.
//
// It stays thin on purpose. A hooks module may import only relative files and
// `claude-code`: no `node:` module, no Node globals. So every rule it applies
// lives in a dependency-free file under ../cadence-core/bin/lib/, where CI's
// typecheck and test.mjs cover it and the command hooks can share it (the
// `.planning/` walk in lib/git-segments.mjs is the first). This file only wires
// those rules to host events and does its I/O through `$`.
//
// What it does: the band above the prompt, naming the running Cadence agents
// it tracks from subagent start and stop, and redrawn on those and on every
// tool call (Plan 2 of phase 3).
//
// The band and token capture run only with the plugin's `panel` userConfig
// field on, which is off by default. Off, the band draws nothing, so the
// drawing beneath it shows as it was, and no window is kept, no fact written
// and no close rewritten. The pane, the listing filter, the prefix safety net
// and the cache meter run either way. `/cad-panel on` and `/cad-panel off`
// write the field through `$.config.set`, as the `/config` row does, and the
// host reloads the module with the new value.
//
// And token capture (Plan 3, D-10/D-11). It keeps each subagent's last
// `turn.step` window, never `turn.complete`'s sum, and writes it as one
// `step_window` fact through `planning.mjs trace append` for the figureless
// `trace close` that names that agent id. The fact takes that close's own
// `--phase` and `--anchor`, never the STATE.md cursor's, which often names
// another phase. A subagent's own close (an advisory reviewer's tail) runs
// before its last step, so its fact is written at its stop; a coordinator's
// close runs after the stop, so its fact is written just before the close is
// passed on. A window whose close never comes is never written, and at most
// HELD_MAX of them wait at once (PNL-07). A subagent's
// own `trace close` gains the `--agent-id` the host sees, so an advisory
// reviewer's bracket and its fact join. The trace reader folds the fact only
// into a bracket whose return carried no figure, so a return's own figure
// always wins. A write that fails is silent: a record may not change a
// decision.
//
// And the Cadence pane (phase 4), beside the band and the token capture: the
// full picture of the current phase, its rows built by lib/pane-view.mjs. The
// `/cad-panel` command this module registers opens it. Like everything here
// it exists only on hosts with mods, so it adds no skill, no resident
// description and no byte budget (D-01). The pane draws from the snapshot its
// last fetch left and does no I/O while drawing. `/cad-panel` calls `next`
// and then answers its own result in that one's place: a registered command
// has no core for `next` to run, and its own text, an empty one included,
// replaces the line the host prints for a command nobody answered. The band's
// `[ pane ]` button, `p` while the band holds the focus, opens the same pane.
// Docked beside the transcript it draws its own round frame, since the host
// draws only a separator there; inline the host borders it, so it draws none.
// It draws a title row, because the host shows the title only as a tab once
// two panes are open. The next command is a button: `n` while the pane holds
// the focus puts it in the prompt.
//
// And the listing filter (phase 5, D-01). The 30 rung agents' and the six
// contract skills' entries come out of the agent and skill listings the model
// reads, in every session and every repo (D-02): route.mjs picks each agent
// and the skill dispatching it names it, so the descriptions bought nothing.
// It edits the `prompt.attachment` text by lib/listing-filter.mjs's line rule.
// The module never withholds through `agent.offer`, it only watches there:
// withholding would take the type out of dispatch too (`Agent type
// 'cadence:cad-reviewer-low' not found`), and `command.describe` `isHidden`
// only hides the command menu entry.
//
// And the prefix safety net (phase 5, D-07; MOD-04). Cadence commands dispatch
// route.mjs's `agent_type`, already `<plugin name>:<stem>`, since a bare name
// belongs to whoever owns it. An Agent call that still names exactly one of
// Cadence's bare stems gets `<plugin name>:` added here, read from
// `$.plugin.name`, unless an `agent.offer` from a non-`plugin` source named
// that bare agent: the offer observer records those, and a user's own
// `cad-reviewer` goes through as sent. The rule is lib/agent-prefix.mjs; every
// other call goes through as sent.
//
// And the cache meter. The same `turn.step` hands every request's usage, the
// main loop's and each agent's, to lib/cache-meter.mjs. The band counts the
// session's cache breaks once there is one, and the pane shows each loop's hit
// rate and breaks. Live and in memory only; the trace keeps none of it (#309).
//
// Every handler calls `next` exactly once and swallows its own errors (D-12).
//
// git-guard, read-trace and subagent-trace stay command hooks on every host, so
// this module makes no git decision and stands no hook down.

import { planningRootAsync } from '../cadence-core/bin/lib/git-segments.mjs';
import { parseCursor } from '../cadence-core/bin/lib/state-cursor.mjs';
import { bandLine, rosterReconcile, rosterStart, rosterStop } from '../cadence-core/bin/lib/band.mjs';
import { roleOfAgent } from '../cadence-core/bin/lib/rung-agent.mjs';
import { ownedAgent, prefixedAgent } from '../cadence-core/bin/lib/agent-prefix.mjs';
import { filterListing, LISTING_TYPES } from '../cadence-core/bin/lib/listing-filter.mjs';
import { closeArgs, stepWindow, stepWindowArgv, withAgentId } from '../cadence-core/bin/lib/token-capture.mjs';
import { NO_PROJECT_TEXT, PANEL_FIELD, PANEL_OFF_TEXT, PANEL_ON_TEXT, PANEL_USAGE, panelArg, panelOn,
  panelUnchanged, parseResolves, RUN_FAILED, SEAM_TIMEOUT_MS, seamAnswer, seamArgv, sightDraw, sightStart, sightStop,
  singleFlight } from '../cadence-core/bin/lib/pane.mjs';
import { paneView } from '../cadence-core/bin/lib/pane-view.mjs';
import { EMPTY_METER, MAIN, meterDrop, meterStep } from '../cadence-core/bin/lib/cache-meter.mjs';

/**
 * The pane's id and title, held once: `/cad-panel` and anything else that
 * opens the pane open this one.
 */
const PANE_ID = 'cadence';
const PANE = Object.freeze({ id: PANE_ID, title: 'Cadence' });

/**
 * One view segment as a host Text. A style the segment leaves unset is left
 * off the props, never passed as undefined. Box and Text take the same props
 * on every surface, so there is nothing to drop on a desktop.
 * @param {any} Text
 * @param {import('../cadence-core/bin/lib/pane-view.mjs').Segment} s
 */
const segmentText = (Text, s) => Text({ children: s.text, ...(s.color ? { color: s.color } : {}),
  ...(s.bg ? { backgroundColor: s.bg } : {}), ...(s.bold ? { bold: true } : {}), ...(s.dim ? { dimColor: true } : {}) });

/** The pane's button that puts the next command in the prompt: `n` while the pane has the keys. */
const NEXT_KEY = 'n';
/** Cells a frame takes from the body: the border and one cell of padding, each side. */
const FRAME_CELLS = 4;

/** The command that opens the pane. User-facing, so the name is locked (D-01). */
const PANEL_COMMAND = 'cad-panel';

/** The band's button that opens the pane: drawn `[ pane ]`, pressed by `p`. */
const PANE_BUTTON_LABEL = 'pane';
const PANE_BUTTON_KEY = 'p';
const PANE_BUTTON_CELLS = PANE_BUTTON_LABEL.length + 4;

/** `dir/name`, without doubling the separator at a filesystem root. */
const at = (/** @type {string} */ dir, /** @type {string} */ name) =>
  (/[\\/]$/.test(dir) ? dir + name : `${dir}/${name}`);

/**
 * Ask the host to draw the band again (D-08). The draw re-reads STATE.md, so
 * this is all a refresh needs. A throw here never reaches the event's answer.
 * @param {any} $
 */
function redraw($) {
  try {
    $.ui.invalidate('ui.render');
  } catch {
    // the next event tries again
  }
}

/**
 * The most stopped subagents' windows `held` keeps waiting for a close (PNL-07).
 * A close comes right after its subagent's return, so a window still waiting
 * after this many later stops is one no close will ever name; the oldest goes.
 */
const HELD_MAX = 64;

/**
 * @typedef {{windows: Map<string, number>, adopted: Map<string, {phase: string, anchor: string | null}>,
 *   held: Map<string, number>}} Capture
 * `windows`: each running subagent's latest step window. `adopted`: the
 * close a running subagent ran on itself, waiting for its last window.
 * `held`: a stopped Cadence subagent's last window, waiting for its close,
 * at most HELD_MAX of them.
 * Every read-and-forget below happens before the first await, so two
 * handlers interleaving never write one window twice.
 */

/**
 * Run one step-window fact in the project a walk from `start` finds.
 * @param {any} $
 * @param {string} start
 * @param {{phase: string, anchor: string | null}} close the close it prices
 * @param {string} id
 * @param {number} tokens
 */
async function writeFact($, start, close, id, tokens) {
  const root = await planningRootAsync(start, (dir, name) => $.fs.exists(at(dir, name)));
  if (root === null) return;
  await $.process.run(stepWindowArgv($.plugin.root, close.phase, id, tokens, close.anchor),
    { cwd: root, timeoutMs: 10000 });
}

/**
 * A subagent stopped. A Cadence subagent whose own close already named its
 * phase gets its fact now, with the window of its LAST step; the project is
 * the walk from the stop's own `cwd`, the field subagent-trace walks from, so
 * the fact lands in the trace.jsonl the close landed in. Without that close
 * its window is held for the coordinator's.
 * @param {any} $
 * @param {any} e the `classic.SubagentStop` input
 * @param {Capture} c
 */
async function stopped($, e, c) {
  try {
    const id = e.agent_id;
    if (typeof id !== 'string') return;
    const tokens = c.windows.get(id);
    const close = c.adopted.get(id);
    c.windows.delete(id);
    c.adopted.delete(id);
    if (tokens === undefined || roleOfAgent(e.agent_type) === null) return;
    if (close === undefined) {
      // Re-inserted, so a Map's insertion order stays oldest-first.
      c.held.delete(id);
      c.held.set(id, tokens);
      if (c.held.size > HELD_MAX) c.held.delete(c.held.keys().next().value);
      return;
    }
    await writeFact($, typeof e.cwd === 'string' && e.cwd ? e.cwd : await $.session.cwd(), close, id, tokens);
  } catch {
    // no record this time; the bracket stays figureless
  }
}

/**
 * A Bash call is about to run. When it is a figureless `trace close` naming a
 * stopped Cadence subagent, write that subagent's held window under the
 * close's own phase first. When it names a subagent still running, keep the
 * close for its stop. A close carrying `--tokens` needs no fact.
 * @param {any} $
 * @param {any} e the event as it goes to `next`, rewrite included
 * @param {Capture} c
 */
async function closing($, e, c) {
  try {
    if (e.tool !== 'Bash') return;
    const close = closeArgs(e.command);
    if (close === null) return;
    const id = close.agentId;
    const tokens = c.held.get(id);
    c.held.delete(id);
    if (close.priced) return;
    if (tokens === undefined) {
      if (c.windows.has(id)) c.adopted.set(id, { phase: close.phase, anchor: close.anchor });
      return;
    }
    await writeFact($, await $.session.cwd(), close, id, tokens);
  } catch {
    // no record this time; the bracket stays figureless
  }
}

/**
 * @typedef {{snapshot: import('../cadence-core/bin/lib/pane.mjs').Snapshot | null, open: boolean,
 *   kick: (task: () => unknown) => Promise<void>}} Pane
 * `snapshot`: what the pane's last fetch read, or null before the first one
 * settles. `open`: whether the pane is up, so a fetch is worth running.
 * `kick`: the pane's single-flight runner.
 */

/**
 * Hand the pane a fetch when it is open, without waiting on it, so no event's
 * answer ever waits on a fetch.
 * @param {any} $
 * @param {Pane} p
 */
function refresh($, p) {
  if (!p.open) return;
  void p.kick(() => fetchPane($, p));
}

/**
 * Read what the pane shows, keep it, and ask for a draw. Never throws, and
 * always leaves a snapshot, failed or not.
 * @param {any} $
 * @param {Pane} p
 */
async function fetchPane($, p) {
  if (!p.open) return;
  try {
    // A pane whose drawing threw is dropped without a `ui.close` reaching
    // the hooks, so ask the engine whether it is still up.
    const panes = await $.ui.panes();
    if (Array.isArray(panes) && !panes.some((x) => x && x.id === PANE_ID)) {
      p.open = false;
      return;
    }
  } catch {
    // no list: fetch anyway
  }
  /** @type {import('../cadence-core/bin/lib/pane.mjs').Snapshot} */
  const read = { cursor: null, status: { ok: false, reason: 'not-read' }, captures: { ok: false, reason: 'not-read' },
    spend: null, resolves: [], sessionModel: null };
  try {
    const root = await planningRootAsync(await $.session.cwd(), (dir, name) => $.fs.exists(at(dir, name)));
    if (root === null) {
      read.status = read.captures = { ok: false, reason: 'no-planning-dir' };
    } else {
      [read.cursor, read.status, read.captures, read.resolves, read.sessionModel] = await Promise.all([
        readCursor($, root), runSeam($, root, ['status']), runSeam($, root, ['capture-check']),
        readResolves($, root), sessionModel($)]);
      // The spend describes status's derived phase (D-05); none, no run.
      const current = read.status.ok ? read.status.value.current : null;
      if (current !== null && current !== undefined) {
        read.spend = await runSeam($, root, ['trace', 'render', '--phase', String(current)]);
      }
    }
  } catch {
    // no walk: nothing read
  }
  p.snapshot = read;
  redraw($);
}

/**
 * The project's STATE.md cursor, or null when it is missing or unreadable:
 * the band's feed (D-03).
 * @param {any} $
 * @param {string} root
 */
async function readCursor($, root) {
  try {
    return parseCursor(await $.fs.read(at(root, '.planning/STATE.md')));
  } catch {
    return null;
  }
}

/**
 * The resolve events in the project's trace.jsonl. A read that rejects (no
 * file, or one over the host's 4 MiB cap) yields none.
 * @param {any} $
 * @param {string} root
 */
async function readResolves($, root) {
  try {
    return parseResolves(await $.fs.read(at(root, '.planning/trace.jsonl')));
  } catch {
    return [];
  }
}

/**
 * The session's model, for a resolve that routed none, or null unread.
 * @param {any} $
 * @returns {Promise<string | null>}
 */
async function sessionModel($) {
  try {
    const m = await $.session.model();
    return typeof m === 'string' && m ? m : null;
  } catch {
    return null;
  }
}

/**
 * One `planning.mjs` subcommand against the project, its answer parsed. The
 * pane re-derives nothing in-process: planning-files imports `node:fs`, and a
 * second derivation would be a second answer (D-04).
 * @param {any} $
 * @param {string} root
 * @param {readonly string[]} args
 * @returns {Promise<import('../cadence-core/bin/lib/pane.mjs').Seam>}
 */
async function runSeam($, root, args) {
  try {
    const ran = await $.process.run(seamArgv($.plugin.root, root, args), { cwd: root, timeoutMs: SEAM_TIMEOUT_MS });
    return seamAnswer(ran && ran.stdout);
  } catch {
    return RUN_FAILED;
  }
}

/**
 * Open the pane in the project a walk from the session's directory finds, and
 * start its fetch without waiting on it. The answer is the command's text: the
 * no-project line, the reason an open waits undrawn, or none once it is drawn.
 * @param {any} $
 * @param {Pane} p
 */
async function openPane($, p) {
  try {
    const root = await planningRootAsync(await $.session.cwd(), (dir, name) => $.fs.exists(at(dir, name)));
    if (root === null) return { text: NO_PROJECT_TEXT };
    const opened = await $.ui.open({ id: PANE.id, title: PANE.title });
    p.open = true;
    refresh($, p);
    // An empty text, never a missing one: only a text replaces the host's own
    // "no command.run hook answered it" line (measured on 2.1.289).
    return opened && opened.isPlaced === false ? { text: String(opened.reason) } : { text: '' };
  } catch {
    return { text: 'The Cadence pane did not open.' };
  }
}

/**
 * Write the `panel` setting, as its `/config` row would. Off closes the pane
 * first: the write reloads the module, and the pane goes with the band. The
 * answer is the command's text, the host's deny included.
 * @param {any} $
 * @param {Pane} p
 * @param {boolean} value
 */
async function setPanel($, p, value) {
  if (!value) {
    try {
      await $.ui.close({ id: PANE_ID });
    } catch {
      // not up
    }
    p.open = false;
  }
  try {
    const set = await $.config.set({ key: `${$.plugin.name}.${PANEL_FIELD}`, value });
    if (set && set.deny !== undefined) return { text: panelUnchanged(String(set.deny)) };
  } catch {
    return { text: panelUnchanged('') };
  }
  return { text: value ? PANEL_ON_TEXT : PANEL_OFF_TEXT };
}

/**
 * @param {any} on the host's hook registrar
 * @param {unknown} [options] the plugin's userConfig values; a change reloads
 *   the module, so they are fixed for this activation
 */
export function register(on, options) {
  // The band and token capture run only with the `panel` setting on, off by
  // default.
  const panel = panelOn(options);
  // The Cadence agents running in this session (D-07). Every write is
  // `roster = transition(roster, ...)` with its await done first, so two
  // handlers interleaving never write back a stale roster.
  /** @type {readonly {id: string, role: string, rung: string}[]} */
  let roster = [];
  // When the module first saw each roster agent, and its host type: the
  // pane's, kept beside the roster so the roster's shape stays phase 3's.
  /** @type {readonly import('../cadence-core/bin/lib/pane.mjs').Sight[]} */
  let sights = [];
  /** @type {Pane} */
  const pane = { snapshot: null, open: false, kick: singleFlight() };
  /** @type {Capture} */
  const capture = { windows: new Map(), adopted: new Map(), held: new Map() };
  // The session's cache meter. Like the roster, every write is
  // `meter = meterStep(meter, ...)`.
  let meter = EMPTY_METER;
  const { windows } = capture;
  // Bare agent names a non-`plugin` `agent.offer` named (MOD-04). It only
  // grows: an agent deleted mid-session stays owned, which errs toward sending
  // the user's name as written.
  /** @type {Set<string>} */
  const owned = new Set();

  // Pass-through: `e` goes down unchanged (D-12 leaves Phase 6 its effort
  // override here). A subagent's step that reports usage replaces its window,
  // so the last step wins, with the `panel` setting on. Every step, main's
  // too, goes to the cache meter, and a break or an open pane asks for a draw.
  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e);
    try {
      const w = panel && typeof e.agentId === 'string' ? stepWindow(result && result.usage) : null;
      if (w !== null) windows.set(e.agentId, w);
    } catch {
      // a step we could not read prices nothing
    }
    try {
      const before = meter.breaks;
      meter = meterStep(meter, typeof e.agentId === 'string' ? e.agentId : MAIN, e.model, e.messageCount,
        result && result.usage);
      if (meter.breaks !== before || pane.open) redraw($);
    } catch {
      // a step we could not read counts nothing
    }
    return result;
  });

  on('classic.SubagentStart', async ($, e, next) => {
    const answer = await next(e);
    try {
      const session = await $.session.id();
      roster = rosterStart(roster, e, session);
      // The band's reconcile may have added this agent already; its type and
      // start still count.
      if (roster.some((a) => a.id === e.agent_id)) sights = sightStart(sights, e.agent_id, e.agent_type, Date.now());
    } catch {
      // the next draw's reconcile adds what this missed
    }
    redraw($);
    refresh($, pane);
    return answer;
  });

  on('classic.SubagentStop', async ($, e, next) => {
    const answer = await next(e);
    try {
      roster = rosterStop(roster, e.agent_id);
      sights = sightStop(sights, e.agent_id);
      meter = meterDrop(meter, e.agent_id);
    } catch {
      // the next draw's reconcile drops what this missed
    }
    redraw($);
    refresh($, pane);
    if (panel) await stopped($, e, capture);
    return answer;
  });

  // A `cursor set` or `renumber` is a Bash call, and they are the only STATE
  // writers, so redrawing after each tool call shows a cursor change as soon as
  // it lands. A write from outside the session shows at the next event. No timer.
  //
  // With the `panel` setting on, a subagent's own `planning.mjs trace close`
  // gains `--agent-id` here (D-11), and any figureless close that names an
  // agent id prices it from its window.
  // An Agent call naming a bare Cadence stem gains the plugin's prefix (phase 5,
  // D-07) as a safety net, unless the offer observer below saw a project or
  // user agent of that bare name. Anything that goes wrong before `next` sends
  // the event exactly as the model wrote it.
  on('tool.call', async ($, e, next) => {
    let sent = e;
    try {
      if (panel && e.tool === 'Bash' && typeof e.agentId === 'string') {
        const rewritten = withAgentId(e.command, e.agentId);
        if (rewritten !== null) sent = { ...e, command: rewritten };
      } else if (e.tool === 'Agent') {
        const type = prefixedAgent(e.subagent_type, $.plugin.name, owned);
        if (type !== null) sent = { ...e, subagent_type: type };
      }
    } catch {
      sent = e;
    }
    if (panel) await closing($, sent, capture);
    const result = await next(sent);
    redraw($);
    refresh($, pane);
    return result;
  });

  // The offer observer (MOD-04). The listing batch reaches here before the
  // first Agent call, so every project and user agent is known by then. No
  // matcher: a matcher cannot say "any source but `plugin`". It passes `e`
  // through and returns what `next` returned, never `isOffered: false`.
  on('agent.offer', async ($, e, next) => {
    try {
      const name = ownedAgent(e);
      if (name !== null) owned.add(name);
    } catch { /* an offer it cannot read records nothing (D-04) */ }
    return next(e);
  });

  // The two listings, without Cadence's agents and contract skills (phase 5,
  // D-01). It filters what `next` resolved, so a text another hook dropped
  // stays dropped, and anything that throws sends the listing unfiltered.
  on('prompt.attachment', { type: LISTING_TYPES }, async ($, e, next) => {
    const result = await next(e);
    try {
      const text = result.text;
      if (typeof text !== 'string') return result;
      const kept = filterListing(e.type, text);
      return kept === text ? result : { text: kept };
    } catch {
      return result;
    }
  });

  // The band. AbovePrompt holds one tree, so the band goes in a column above
  // whatever the mods beneath drew, never in place of it. No band with the
  // `panel` setting off, while a survey holds the row, or outside a Cadence
  // project (D-06).
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const drawn = await next(e);
    try {
      if (!panel || e.props.hasSurvey) return drawn;
      const root = await planningRootAsync(await $.session.cwd(), (dir, name) => $.fs.exists(at(dir, name)));
      if (root === null) return drawn;
      let cursor = null;
      try {
        cursor = parseCursor(await $.fs.read(at(root, '.planning/STATE.md')));
      } catch {
        // unreadable is the same as absent: the /cad-progress line
      }
      try {
        const list = await $.agent.list();
        roster = rosterReconcile(roster, list);
      } catch {
        // no list: draw the roster the start and stop events built
      }
      const { Box, Text, Button } = $.ui.resolve(e);
      if (typeof Button !== 'function') {
        const band = Text({ wrap: 'truncate-end', children: bandLine(cursor, roster, e.props.bodyColumns, meter.breaks) });
        return Box({ flexDirection: 'column', children: [band, drawn] });
      }
      // The pane's button beside the line, which takes what is left. A letter,
      // never a digit: a bare digit in an empty composer presses a band Button.
      const line = bandLine(cursor, roster, Math.max(0, e.props.bodyColumns - PANE_BUTTON_CELLS - 1), meter.breaks);
      const button = Button({ label: PANE_BUTTON_LABEL, hotkey: PANE_BUTTON_KEY,
        onPress: () => { openPane($, pane).catch(() => {}); } });
      const band = Box({ flexDirection: 'row', gap: 1, children: [Text({ wrap: 'truncate-end', children: line }), button] });
      return Box({ flexDirection: 'column', children: [band, drawn] });
    } catch {
      return drawn;
    }
  });

  // --- the pane --------------------------------------------------------------

  on('session.start', async ($, e, next) => {
    try {
      await $.command.register({ name: PANEL_COMMAND, immediate: true, argumentHint: 'on | off',
        description: 'Open the Cadence pane: plans, running agents, UAT, captures, spend and next command' });
    } catch {
      // no command this session; the band still draws
    }
    return next(e);
  });

  // `/cad-panel` opens the pane whatever the setting; `on` and `off` write it.
  on('command.run', { command: PANEL_COMMAND }, async ($, e, next) => {
    await next(e);
    const arg = panelArg(e.args);
    if (arg === 'open') return openPane($, pane);
    if (arg === null) return { text: PANEL_USAGE };
    return setPanel($, pane, arg === 'on');
  });

  // `/cad-panel`'s empty answer draws as a bare `cadence:`; draw one dim
  // line in its place. A reason (no project, the open waited) draws as written.
  on('ui.render', { component: 'CommandOutput', props: { command: PANEL_COMMAND } }, async ($, e, next) => {
    const drawn = await next(e);
    try {
      // The host prints a plugin's answer after its name (`cadence: `).
      const said = String(e.props.text).replace(`${$.plugin.name}:`, '').trim();
      if (said) return drawn;
      const { Box, Text } = $.ui.resolve(e);
      return Box({ paddingLeft: 2, children: [Text({ dimColor: true, children: '⎿  Cadence pane open' })] });
    } catch {
      return drawn;
    }
  });

  // A close marks the pane down, so no event fetches for it.
  on('ui.close', { id: PANE_ID }, async ($, e, next) => {
    const answer = await next(e);
    pane.open = false;
    return answer;
  });

  // The pane draws the last snapshot and awaits nothing but `next`. With no
  // snapshot (a module reloaded while its pane stayed up) the pane is up, so
  // it counts as open and starts the one fetch that leaves a snapshot.
  on('ui.render', { component: 'Pane', requestId: PANE_ID }, async ($, e, next) => {
    const drawn = await next(e);
    try {
      if (pane.snapshot === null) {
        pane.open = true;
        refresh($, pane);
      }
      const { Box, Text, Button } = $.ui.resolve(e);
      sights = sightDraw(sights, roster, Date.now());
      // Docked beside the transcript the pane has a separator only, so it gets
      // a frame; inline above the prompt the host draws a border already.
      const framed = e.props.placement === 'dock';
      const width = Math.max(1, e.props.bodyColumns - (framed ? FRAME_CELLS : 0));
      const title = Box({ flexDirection: 'row', justifyContent: 'space-between', children: [
        Text({ bold: true, color: 'cyan', children: '◆ Cadence' }),
        Text({ dimColor: true, wrap: 'truncate-end', children: typeof Button === 'function' ? `${NEXT_KEY} next` : '' })] });
      const cell = (/** @type {any} */ s) => s.action === 'next' && typeof Button === 'function'
        ? Button({ key: 'next', label: s.text, hotkey: NEXT_KEY, variant: 'primary',
          onPress: () => { $.prompt.fill({ text: s.text, mode: 'replace' }).catch(() => {}); } })
        : segmentText(Text, s);
      const rows = paneView(pane.snapshot, width, roster, sights, meter)
        .map((row) => Box({ flexDirection: 'row', children: row.map(cell) }));
      const body = [title, Text({ children: ' ' }), ...rows];
      return framed
        ? Box({ flexDirection: 'column', borderStyle: 'round', borderColor: 'gray', paddingX: 1, children: body })
        : Box({ flexDirection: 'column', children: body });
    } catch {
      return drawn;
    }
  });
}

